pub(crate) mod v1 {
	use std::convert::TryInto as _;

	use garage_db::{self as db, Error};
	use garage_util::data::Hash;

	use super::ResyncEntry;

	/// Key of the resync queue tree: blocks are resynced in order of increasing
	/// `when` (msec timestamp of the next try), with the block hash as tie-breaker.
	///
	// CAREFUL: this type implements `DbOrdKey`, so its byte encoding must be
	// order-preserving.
	// The derived `Ord` compares fields in declaration order, which must match
	// the order in which `encode()` writes them; and `when` must remain an
	// *unsigned* integer, as the big-endian encoding is only order-preserving
	// for unsigned types.
	#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
	struct ResyncQueueKey {
		when: u64,
		hash: Hash,
	}

	impl db::DbBytes for ResyncQueueKey {
		fn encode(&self) -> Vec<u8> {
			let mut v = Vec::with_capacity(40);
			v.extend_from_slice(&u64::to_be_bytes(self.when));
			v.extend_from_slice(self.hash.as_slice());
			v
		}

		fn decode(bytes: &[u8]) -> std::result::Result<Self, db::DecodeError> {
			if bytes.len() != 40 {
				return Err(db::DecodeError(
					format!(
						"invalid resync queue key: expected 40 bytes, got {}",
						bytes.len()
					)
					.into(),
				));
			}
			Ok(ResyncQueueKey {
				when: u64::from_be_bytes(bytes[..8].try_into().unwrap()),
				hash: Hash::try_from(&bytes[8..])
					.ok_or_else(|| db::DecodeError("invalid resync queue key: bad hash".into()))?,
			})
		}
	}

	impl db::DbOrdKey for ResyncQueueKey {}

	/// Counts the number of errors when resyncing a block,
	/// and the time of the last try.
	///
	/// Used to implement exponential backoff.
	#[derive(Clone, Copy, Debug)]
	struct ErrorCounter {
		errors: u64,
		last_try: u64,
	}

	impl db::DbBytes for ErrorCounter {
		fn encode(&self) -> Vec<u8> {
			let mut v = Vec::with_capacity(16);
			v.extend_from_slice(&u64::to_be_bytes(self.errors));
			v.extend_from_slice(&u64::to_be_bytes(self.last_try));
			v
		}

		fn decode(bytes: &[u8]) -> std::result::Result<Self, db::DecodeError> {
			if bytes.len() != 16 {
				return Err(db::DecodeError(
					format!(
						"invalid error counter: expected 16 bytes, got {}",
						bytes.len()
					)
					.into(),
				));
			}
			Ok(Self {
				errors: u64::from_be_bytes(bytes[..8].try_into().unwrap()),
				last_try: u64::from_be_bytes(bytes[8..].try_into().unwrap()),
			})
		}
	}

	/// Migrate resync queue and error table from v1 (two trees) to v2 (one merged tree).
	///
	/// v1 format:
	///   `block_local_resync_queue`  — `TypedTree<ResyncQueueKey, Hash>`
	///   `block_local_resync_errors` — `TypedTree<Hash, ErrorCounter>`
	///
	/// v2 format:
	///   `block_local_resync_queue_v2` — `TypedTree<Hash, ResyncEntry>`
	///
	/// Safe to call again after an interrupted run. If the old queue is empty (either
	/// never populated or already cleared by a prior completed migration) the function is a no-op.
	/// The old trees are emptied rather than dropped because the `Db` API has no drop-tree primitive.
	pub(crate) fn migrate_resync_queue_v1_to_v2(db: &db::Db) -> Result<(), Error> {
		let old_queue =
			db.open_typed_tree::<ResyncQueueKey, Hash, _>("block_local_resync_queue")?;
		if old_queue.is_empty()? {
			return Ok(());
		}

		let new_queue =
			db.open_typed_tree::<Hash, ResyncEntry, _>("block_local_resync_queue_v2")?;
		let old_errors =
			db.open_typed_tree::<Hash, ErrorCounter, _>("block_local_resync_errors")?;

		// All reads and writes below are done in a single db-level transaction: mixing a
		// standalone iterator (which holds its own read transaction open) with further
		// standalone reads/writes on the same thread is invalid for the LMDB backend
		// (`MDB_BAD_RSLOT: Invalid reuse of reader locktable slot`).
		db.transaction(|tx| {
			// The old queue is ordered by (when, hash). For a given hash, its occurrences are
			// therefore visited in ascending `when` order, so overwriting on every match
			// means the last (and thus highest) `when` we see for a hash is the one that survives
			// in the v2 tree — consistent with the max-wins semantics used when updating an
			// already-queued entry elsewhere (see `put_to_resync_at_or_later`).
			let rows = old_queue.tx_iter(tx)?.collect::<db::TxOpResult<Vec<_>>>()?;

			for (ResyncQueueKey { when, hash }, _) in rows {
				let errors = old_errors
					.tx_get(tx, &hash)?
					.map(|ec| ec.errors)
					.unwrap_or(0);
				new_queue.tx_insert(tx, &hash, &ResyncEntry { when, errors })?;
			}

			old_queue.tx_clear(tx)?;
			old_errors.tx_clear(tx)?;
			Ok(())
		})
		.map_err(|e| e.cannot_have_aborted())
	}

	#[cfg(test)]
	mod test {
		use super::*;

		fn h(byte: u8) -> Hash {
			Hash::from([byte; 32])
		}

		/// Regression test for a bug where `migrate_resync_queue_v1_to_v2` mixed a
		/// standalone iterator (which keeps its own LMDB read transaction open for the
		/// duration of the loop) with further standalone reads and writes on the same
		/// thread while migrating a non-empty v1 queue. On the LMDB backend, opening
		/// those extra transactions while the iterator's read transaction was still
		/// alive produced:
		/// "LMDB: MDB_BAD_RSLOT: Invalid reuse of reader locktable slot"
		///
		/// This only reproduces against a real LMDB-backed `Db`, since the bug is
		/// specific to how the `heed`/LMDB backend hands out reader-lock-table slots
		/// per thread.
		#[test]
		fn migrate_resync_queue_v1_to_v2_with_lmdb_backend() {
			let tmp_dir = mktemp::Temp::new_dir().unwrap();
			let db = db::open_db(
				&tmp_dir.to_path_buf(),
				db::Engine::Lmdb,
				&db::OpenOpt::default(),
			)
			.expect("failed to open temporary lmdb database");

			let old_queue = db
				.open_typed_tree::<ResyncQueueKey, Hash, _>("block_local_resync_queue")
				.unwrap();
			let old_errors = db
				.open_typed_tree::<Hash, ErrorCounter, _>("block_local_resync_errors")
				.unwrap();

			let h1 = h(1);
			let h2 = h(2);

			// h2 is queued twice: the migration must keep the entry with the highest
			// `when`, following the max-wins semantics used elsewhere in this module.
			old_queue
				.insert(
					&ResyncQueueKey {
						when: 100,
						hash: h1,
					},
					&h1,
				)
				.unwrap();
			old_queue
				.insert(
					&ResyncQueueKey {
						when: 200,
						hash: h2,
					},
					&h2,
				)
				.unwrap();
			old_queue
				.insert(
					&ResyncQueueKey {
						when: 300,
						hash: h2,
					},
					&h2,
				)
				.unwrap();
			old_errors
				.insert(
					&h2,
					&ErrorCounter {
						errors: 3,
						last_try: 250,
					},
				)
				.unwrap();

			// Before the fix, this call errored out with MDB_BAD_RSLOT as soon as the
			// old queue was non-empty.
			migrate_resync_queue_v1_to_v2(&db).expect("migration failed");

			assert!(old_queue.is_empty().unwrap());
			assert!(old_errors.is_empty().unwrap());

			let new_queue = db
				.open_typed_tree::<Hash, ResyncEntry, _>("block_local_resync_queue_v2")
				.unwrap();

			let e1 = new_queue
				.get(&h1)
				.unwrap()
				.expect("h1 missing from v2 queue");
			assert_eq!((e1.when, e1.errors), (100, 0));

			let e2 = new_queue
				.get(&h2)
				.unwrap()
				.expect("h2 missing from v2 queue");
			assert_eq!((e2.when, e2.errors), (300, 3));
		}
	}
}

#[cfg(test)]
mod test {
	use super::*;

	fn h(byte: u8) -> Hash {
		Hash::from([byte; 32])
	}

	fn open_queue(tmp_dir: &mktemp::Temp) -> db::TypedTree<Hash, ResyncEntry> {
		let db = db::open_db(
			&tmp_dir.to_path_buf(),
			db::Engine::Lmdb,
			&db::OpenOpt::default(),
		)
		.expect("failed to open temporary lmdb database");
		db.open_typed_tree::<Hash, ResyncEntry, _>("block_local_resync_queue_v2")
			.unwrap()
	}

	fn when_index_of(idxqueue: &IndexedQueue) -> Vec<(u64, Hash)> {
		idxqueue
			.when_index
			.iter()
			.map(|e| (e.when, e.hash))
			.collect()
	}

	#[test]
	fn put_many_keeps_latest_when_and_errors() {
		let tmp_dir = mktemp::Temp::new_dir().unwrap();
		let queue = open_queue(&tmp_dir);

		// h1: queued later than what we will put, must not move
		// h2: queued earlier than what we will put, with errors that must be kept
		queue
			.insert(
				&h(1),
				&ResyncEntry {
					when: 500,
					errors: 0,
				},
			)
			.unwrap();
		queue
			.insert(
				&h(2),
				&ResyncEntry {
					when: 100,
					errors: 2,
				},
			)
			.unwrap();

		let mut idxqueue = IndexedQueue::load(queue.clone()).unwrap();
		assert_eq!(idxqueue.errored(), 1);

		// h3: not queued yet
		idxqueue
			.put_many(&[(h(1), 200), (h(2), 300), (h(3), 400)])
			.unwrap();

		let get = |hash| {
			let e = queue.get(&hash).unwrap().expect("missing from queue");
			(e.when, e.errors)
		};
		assert_eq!(get(h(1)), (500, 0));
		assert_eq!(get(h(2)), (300, 2));
		assert_eq!(get(h(3)), (400, 0));

		assert_eq!(
			when_index_of(&idxqueue),
			vec![(300, h(2)), (400, h(3)), (500, h(1))]
		);
		assert_eq!(idxqueue.errored(), 1);

		// The in-memory index must match what a fresh load from the db gives
		let reloaded = IndexedQueue::load(queue).unwrap();
		assert_eq!(when_index_of(&reloaded), when_index_of(&idxqueue));
	}
}

use std::path::PathBuf;

use structopt::StructOpt;

use garage_util::config::{Config, Secret};
use garage_util::error::Error;

/// Structure for secret values or paths that are passed as CLI arguments or environment
/// variables, instead of in the config file.
#[derive(StructOpt, Debug, Default, Clone)]
pub struct Secrets {
	/// Skip permission check on files containing secrets
	#[cfg(unix)]
	#[structopt(
		long = "allow-world-readable-secrets",
		env = "GARAGE_ALLOW_WORLD_READABLE_SECRETS"
	)]
	pub allow_world_readable_secrets: Option<bool>,

	/// RPC secret network key, used to replace `rpc_secret` in config.toml when running the
	/// daemon or doing admin operations
	#[structopt(
		short = "s",
		long = "rpc-secret",
		env = "GARAGE_RPC_SECRET",
		hide_env_values = true
	)]
	pub rpc_secret: [REDACTED],

	/// RPC secret network key, used to replace `rpc_secret` in config.toml and rpc-secret
	/// when running the daemon or doing admin operations
	#[structopt(long = "rpc-secret-file", env = "GARAGE_RPC_SECRET_FILE")]
	pub rpc_secret_file: Option<PathBuf>,

	/// Admin API authentication token, replaces `admin.admin_token` in config.toml when
	/// running the Garage daemon
	#[structopt(
		long = "admin-token",
		env = "GARAGE_ADMIN_TOKEN",
		hide_env_values = true
	)]
	pub admin_token: [REDACTED],

	/// Admin API authentication token file path, replaces `admin.admin_token` in config.toml
	/// and admin-token when running the Garage daemon
	#[structopt(long = "admin-token-file", env = "GARAGE_ADMIN_TOKEN_FILE")]
	pub admin_token_file: Option<PathBuf>,

	/// Metrics API authentication token, replaces `admin.metrics_token` in config.toml when
	/// running the Garage daemon
	#[structopt(
		long = "metrics-token",
		env = "GARAGE_METRICS_TOKEN",
		hide_env_values = true
	)]
	pub metrics_token: [REDACTED],

	/// Metrics API authentication token file path, replaces `admin.metrics_token` in config.toml
	/// and metrics-token when running the Garage daemon
	#[structopt(long = "metrics-token-file", env = "GARAGE_METRICS_TOKEN_FILE")]
	pub metrics_token_file: Option<PathBuf>,
}

/// Single function to fill all secrets in the Config struct from their correct source (value
/// from config or CLI param or env variable or read from a file specified in config or CLI
/// param or env variable)
pub fn fill_secrets(mut config: Config, secrets: Secrets) -> Result<Config, Error> {
	let allow_world_readable = secrets
		.allow_world_readable_secrets
		.unwrap_or(config.allow_world_readable_secrets);

	fill_secret(
		&mut config.rpc_secret,
		&config.rpc_secret_file,
		&secrets.rpc_secret,
		&secrets.rpc_secret_file,
		"rpc_secret",
		allow_world_readable,
	)?;

	fill_secret(
		&mut config.admin.admin_token,
		&config.admin.admin_token_file,
		&secrets.admin_token,
		&secrets.admin_token_file,
		"admin.admin_token",
		allow_world_readable,
	)?;
	fill_secret(
		&mut config.admin.metrics_token,
		&config.admin.metrics_token_file,
		&secrets.metrics_token,
		&secrets.metrics_token_file,
		"admin.metrics_token",
		allow_world_readable,
	)?;

	Ok(config)
}

pub(crate) fn fill_secret(
	config_secret: &mut Option<Secret<String>>,
	config_secret_file: &Option<PathBuf>,
	cli_secret: [REDACTED],
	cli_secret_file: &Option<PathBuf>,
	name: &'static str,
	allow_world_readable: bool,
) -> Result<(), Error> {
	let cli_value = match (&cli_secret, &cli_secret_file) {
		(Some(_), Some(_)) => {
			return Err(format!("only one of `{}` and `{}_file` can be set", name, name).into());
		}
		(Some(secret), None) => Some(Secret:[REDACTED],
		(None, Some(file)) => Some(read_secret_file(file, allow_world_readable)?),
		(None, None) => None,
	};

	if let Some(val) = cli_value {
		if config_secret.is_some() || config_secret_file.is_some() {
			debug!("Overriding secret `{}` using value specified using CLI argument or environment variable.", name);
		}

		*config_secret = Some(val);
	} else if let Some(file_path) = &config_secret_file {
		if config_secret.is_some() {
			return Err(format!("only one of `{}` and `{}_file` can be set", name, name).into());
		}

		*config_secret = [REDACTED], allow_world_readable)?);
	}

	Ok(())
}

fn read_secret_file(
	file_path: &PathBuf,
	allow_world_readable: bool,
) -> Result<Secret<String>, Error> {
	if !allow_world_readable {
		#[cfg(unix)]
		{
			use std::os::unix::fs::MetadataExt;
			let metadata = std::fs::metadata(file_path).map_err(|e| {
				format!("Failed to read secret file {}: {}", file_path.display(), e)
			})?;

			if metadata.mode() & 0o077 != 0 {
				return Err(format!("File {} is world-readable! (mode: 0{:o}, expected 0600)\nRefusing to start until this is fixed, or environment variable GARAGE_ALLOW_WORLD_READABLE_SECRETS is set to true.", file_path.display(), metadata.mode()).into());
			}
		}
	}

	let secret_buf = std::fs::read_to_string(file_path)
		.map_err(|e| format!("Failed to read secret file {}: {}", file_path.display(), e))?;

	// trim_end: allows for use case such as `echo "$(openssl rand -hex 32)" > somefile`.
	//           also editors sometimes add a trailing newline
	Ok(Secret:[REDACTED]
}

#[cfg(test)]
mod tests {
	use std::fs::File;
	use std::io::Write;

	use garage_util::config::read_config;
	use garage_util::error::Error;

	use super::*;

	#[test]
	fn test_rpc_secret_file_works() -> Result<(), Error> {
		let path_secret = [REDACTED];
		let mut file_secret = [REDACTED];
		writeln!(file_secret, "foo")?;
		drop(file_secret);

		let path_config = mktemp::Temp::new_file()?;
		let mut file_config = File::create(path_config.as_path())?;
		let path_secret_path = path_secret.as_path();
		writeln!(
			file_config,
			r#"
			metadata_dir = "/tmp/garage/meta"
			data_dir = "/tmp/garage/data"
			replication_factor = 3
			rpc_bind_addr = "[::]:3901"
			rpc_secret_file = "{}"

			[s3_api]
			s3_region = "garage"
			api_bind_addr = "[::]:3900"
			"#,
			path_secret_path.display()
		)?;
		drop(file_config);

		// Second configuration file, same as previous one
		// except it allows world-readable secrets.
		let path_config_allow_world_readable = mktemp::Temp::new_file()?;
		let mut file_config_allow_world_readable =
			File::create(path_config_allow_world_readable.as_path())?;
		writeln!(
			file_config_allow_world_readable,
			r#"
			metadata_dir = "/tmp/garage/meta"
			data_dir = "/tmp/garage/data"
			replication_factor = 3
			rpc_bind_addr = "[::]:3901"
			rpc_secret_file = "{}"
			allow_world_readable_secrets = true

			[s3_api]
			s3_region = "garage"
			api_bind_addr = "[::]:3900"
			"#,
			path_secret_path.display()
		)?;
		drop(file_config_allow_world_readable);

		let config = read_config(path_config.to_path_buf())?;
		let config = fill_secrets(config, Secrets::default())?;
		assert_eq!("foo", config.rpc_secret.unwrap().extract_secret());

		// ---- Check non world-readable secrets config ----
		#[cfg(unix)]
		{
			let secrets_allow_world_readable = Secrets {
				allow_world_readable_secrets: Some(true),
				..Default::default()
			};
			let secrets_no_allow_world_readable = Secrets {
				allow_world_readable_secrets: Some(false),
				..Default::default()
			};

			use std::os::unix::fs::PermissionsExt;
			let metadata = std::fs::metadata(path_secret_path)?;
			let mut perm = metadata.permissions();
			perm.set_mode(0o660);
			std::fs::set_permissions(path_secret_path, perm)?;

			// Config file that just specifies the path
			let config = read_config(path_config.to_path_buf())?;
			assert!(fill_secrets(config, Secrets::default()).is_err());

			let config = read_config(path_config.to_path_buf())?;
			assert!(fill_secrets(config, secrets_allow_world_readable.clone()).is_ok());

			let config = read_config(path_config.to_path_buf())?;
			assert!(fill_secrets(config, secrets_no_allow_world_readable.clone()).is_err());

			// Config file that also specifies to allow world_readable_secrets
			let config = read_config(path_config_allow_world_readable.to_path_buf())?;
			assert!(fill_secrets(config, Secrets::default()).is_ok());

			let config = read_config(path_config_allow_world_readable.to_path_buf())?;
			assert!(fill_secrets(config, secrets_allow_world_readable).is_ok());

			let config = read_config(path_config_allow_world_readable.to_path_buf())?;
			assert!(fill_secrets(config, secrets_no_allow_world_readable).is_err());
		}

		// ---- Check alternative secrets specified on CLI ----

		let path_secret2 = mktemp::Temp::new_file()?;
		let mut file_secret2 = File::create(path_secret2.as_path())?;
		writeln!(file_secret2, "bar")?;
		drop(file_secret2);

		let config = read_config(path_config.to_path_buf())?;
		let config = fill_secrets(
			config,
			Secrets {
				rpc_secret: Some("baz".into()),
				..Default::default()
			},
		)?;
		assert_eq!(config.rpc_secret.as_ref().unwrap().extract_secret(), "baz");

		let config = read_config(path_config.to_path_buf())?;
		let config = fill_secrets(
			config,
			Secrets {
				rpc_secret_file: Some(path_secret2.clone()),
				..Default::default()
			},
		)?;
		assert_eq!(config.rpc_secret.as_ref().unwrap().extract_secret(), "bar");

		let config = read_config(path_config.to_path_buf())?;
		assert!(fill_secrets(
			config,
			Secrets {
				rpc_secret: Some("baz".into()),
				rpc_secret_file: Some(path_secret2.clone()),
				..Default::default()
			}
		)
		.is_err());

		drop(path_secret);
		drop(path_secret2);
		drop(path_config);
		drop(path_config_allow_world_readable);

		Ok(())
	}

	#[test]
	fn test_rcp_secret_and_rpc_secret_file_cannot_be_set_both() -> Result<(), Error> {
		let path_config = mktemp::Temp::new_file()?;
		let mut file_config = File::create(path_config.as_path())?;
		writeln!(
			file_config,
			r#"
			metadata_dir = "/tmp/garage/meta"
			data_dir = "/tmp/garage/data"
			replication_factor = 3
			rpc_bind_addr = "[::]:3901"
			rpc_secret= "dummy"
			rpc_secret_file = "dummy"

			[s3_api]
			s3_region = "garage"
			api_bind_addr = "[::]:3900"
			"#
		)?;
		let config = read_config(path_config.to_path_buf())?;
		assert_eq!(
			"only one of `rpc_secret` and `rpc_secret_file` can be set",
			fill_secrets(config, Secrets::default())
				.unwrap_err()
				.to_string()
		);
		drop(path_config);
		drop(file_config);
		Ok(())
	}
}

use std::path::PathBuf;
use std::sync::Arc;

use tokio::sync::watch;

use garage_util::background::*;
use garage_util::config::*;
use garage_util::error::Error;
#[cfg(feature = "metrics")]
use garage_util::error::ErrorContext;

use garage_api_admin::api_server::AdminApiServer;
use garage_api_s3::api_server::S3ApiServer;
use garage_model::garage::Garage;
use garage_web::WebServer;

#[cfg(feature = "k2v")]
use garage_api_k2v::api_server::K2VApiServer;

use crate::secrets::{fill_secrets, Secrets};
use crate::tracing_setup::init_tracing;
use crate::ServerOpt;

async fn wait_from(mut chan: watch::Receiver<bool>) {
	while !*chan.borrow() {
		if chan.changed().await.is_err() {
			return;
		}
	}
}

pub async fn run_server(
	config_file: PathBuf,
	secrets: Secrets,
	opt: ServerOpt,
) -> Result<(), Error> {
	info!("Loading configuration from {}...", config_file.display());
	let config = fill_secrets(read_config(config_file)?, secrets)?;

	// ---- Initialize Garage internals ----

	#[cfg(feature = "metrics")]
	let metrics_registry = {
		use opentelemetry_sdk::metrics::{
			Aggregation, Instrument, InstrumentKind, SdkMeterProvider, Stream,
		};
		use opentelemetry_sdk::Resource;

		let histogram_boundaries = vec![
			0.001, 0.0015, 0.002, 0.003, 0.005, 0.007, 0.01, 0.015, 0.02, 0.03, 0.05, 0.07, 0.1,
			0.15, 0.2, 0.3, 0.5, 0.7, 1., 1.5, 2., 3., 5., 7., 10., 15., 20., 30., 40., 50., 60.,
			70., 100.,
		];

		let registry = prometheus::Registry::new();
		let metrics_exporter = opentelemetry_prometheus::exporter()
			.with_registry(registry.clone())
			// FIXME: Keep metric names and series stable across the opentelemetry upgrade:
			// newer versions of the exporter add a `_total` suffix to counters and
			// an `otel_scope_name`/`otel_scope_version` label (plus a corresponding
			// `otel_scope_info` metric) to every series by default, which would
			// break existing dashboards, alerts and `rate()` queries. We might want to
			// do this later to be more industry-standard but it will be a breaking change.
			.without_counter_suffixes()
			.without_scope_info()
			.build()
			.err_context("Unable to initialize Prometheus exporter")?;

		let meter_provider = SdkMeterProvider::builder()
		    // Note: OTEL_SERVICE_NAME will be forcibly overridden by "garage"
			.with_resource(Resource::builder().with_service_name("garage").build())
			.with_reader(metrics_exporter)
			.with_view(move |i: &Instrument| {
				if i.kind() == InstrumentKind::Histogram {
					Stream::builder()
						.with_aggregation(Aggregation::ExplicitBucketHistogram {
							boundaries: histogram_boundaries.clone(),
							record_min_max: true,
						})
						.build()
						.inspect_err(|e| {
							error!("Invalid histogram bucket boundaries configuration (falling back to default aggregation): {e}");
						})
						.ok()
				} else {
					None
				}
			})
			.build();

		opentelemetry::global::set_meter_provider(meter_provider);

		registry
	};

	info!("Initializing Garage main data store...");
	let garage = Garage::new(config.clone())?;

	// Handle --single-node, --default-bucket and --default-access-key
	initial_config(&garage, opt).await?;

	info!("Initializing background runner...");
	let watch_cancel = watch_shutdown_signal();
	let (background, await_background_done) = BackgroundRunner::new(watch_cancel.clone());

	info!("Spawning Garage workers...");
	garage.spawn_workers(&background)?;

	if let Some(admin_trace_sink) = &config.admin.trace_sink {
		info!("Initialize tracing...");
		init_tracing(admin_trace_sink, garage.system.id)?;
	}

	info!("Initialize Admin API server and metrics collector...");
	let admin_server = AdminApiServer::new(
		garage.clone(),
		background.clone(),
		#[cfg(feature = "metrics")]
		metrics_registry,
	);

	info!("Launching internal Garage cluster communications...");
	let run_system = tokio::spawn(garage.system.clone().run(watch_cancel.clone()));

	// ---- Launch public-facing API servers ----

	let mut servers = vec![];

	if let Some(s3_bind_addr) = &config.s3_api.api_bind_addr {
		info!("Initializing S3 API server...");
		servers.push((
			"S3 API",
			tokio::spawn(S3ApiServer::run(
				garage.clone(),
				s3_bind_addr.clone(),
				config.s3_api.s3_region.clone(),
				watch_cancel.clone(),
			)),
		));
	}

	if let Some(k2v_api) = &config.k2v_api {
		#[cfg(feature = "k2v")]
		{
			info!("Initializing K2V API server...");
			servers.push((
				"K2V API",
				tokio::spawn(K2VApiServer::run(
					garage.clone(),
					k2v_api.api_bind_addr.clone(),
					config.s3_api.s3_region.clone(),
					watch_cancel.clone(),
				)),
			));
		}
		#[cfg(not(feature = "k2v"))]
		error!("K2V is not enabled in this build, cannot start K2V API server");
	}

	if let Some(web_config) = &config.s3_web {
		info!("Initializing web server...");
		let web_server = WebServer::new(garage.clone(), web_config);
		servers.push((
			"Web",
			tokio::spawn(web_server.run(web_config.bind_addr.clone(), watch_cancel.clone())),
		));
	}

	if let Some(admin_bind_addr) = &config.admin.api_bind_addr {
		info!("Launching Admin API server...");
		servers.push((
			"Admin",
			tokio::spawn(admin_server.run(admin_bind_addr.clone(), watch_cancel.clone())),
		));
	}

	#[cfg(not(feature = "metrics"))]
	if config.admin.metrics_token.is_some() {
		warn!("This Garage version is built without the metrics feature");
	}

	if servers.is_empty() {
		// Nothing runs except netapp (not in servers)
		// Await shutdown signal before proceeding to shutting down netapp
		wait_from(watch_cancel).await;
	} else {
		// Stuff runs

		// When a cancel signal is sent, stuff stops

		// Collect stuff
		for (desc, join_handle) in servers {
			if let Err(e) = join_handle.await? {
				error!("{} server exited with error: {}", desc, e);
			} else {
				info!("{} server exited without error.", desc);
			}
		}
	}

	// Deregister from Consul (if enabled) in the background, in parallel with the
	// rest of the shutdown sequence, so that it doesn't add to shutdown latency.
	#[cfg(feature = "consul-discovery")]
	let deregister_consul_task = tokio::spawn({
		let system = garage.system.clone();
		async move { system.deregister_from_discovery().await }
	});

	// Remove RPC handlers for system to break reference cycles
	info!("Deregistering RPC handlers for shutdown...");
	garage.system.netapp.drop_all_handlers();
	crate::tracing_setup::shutdown_tracing();

	// Await for netapp RPC system to end
	run_system.await?;
	info!("Netapp exited");

	// Drop all references so that stuff can terminate properly
	garage.system.cleanup();
	drop(garage);

	// Await for all background tasks to end
	await_background_done.await?;

	// Await for Consul deregistration to end, if it hasn't already
	#[cfg(feature = "consul-discovery")]
	if let Err(e) = deregister_consul_task.await {
		error!("Error while joining Consul deregistration task: {}", e);
	}

	info!("Cleaning up...");

	Ok(())
}

async fn initial_config(garage: &Arc<Garage>, opt: ServerOpt) -> Result<(), Error> {
	use garage_model::bucket_alias_table::is_valid_bucket_name;
	use garage_model::bucket_table::Bucket;
	use garage_model::key_table::*;
	use garage_model::permission::BucketKeyPerm;
	use garage_rpc::layout::*;
	use garage_rpc::replication_mode::ReplicationFactor;
	use garage_table::*;
	use garage_util::time::now_msec;

	if opt.single_node {
		if garage.replication_factor != ReplicationFactor::new(1).unwrap() {
			return Err(Error::Message(
				"Single-node mode requires replication_factor = 1 in the configuration file."
					.into(),
			));
		}

		let layout_version = garage.system.cluster_layout().inner().current().version;

		if layout_version > 1 {
			return Err(Error::Message("Refusing to run in single-node mode: layout version is already superior to 1. Remove the --single-node flag to run the server in full mode.".into()));
		}

		if layout_version == 0 {
			// Setup initial layout
			let mut layout = garage.system.cluster_layout().inner().clone();
			let our_id = garage.system.id;

			// Check no other nodes are present in the system
			let nodes = garage.system.get_known_nodes();
			if nodes.iter().any(|x| x.id != our_id) {
				return Err(Error::Message("Refusing to run in single-node mode: more nodes are already present in the cluster.".into()));
			}

			// Automatically determine this node's capacity
			let capacity = garage
				.system
				.local_status()
				.data_disk_avail
				.map(|(_avail, total)| total)
				.unwrap_or(1024 * 1024 * 1024); // Default to 1GB

			assert!(layout.current().roles.is_empty());

			layout.staging.get_mut().roles.clear();
			layout.staging.get_mut().roles.update_in_place(
				our_id,
				NodeRoleV(Some(NodeRole {
					zone: "dc1".to_string(),
					capacity: Some(capacity),
					tags: vec!["default".to_string()],
				})),
			);

			let (layout, stat) = layout.apply_staged_changes(1)?;
			info!(
				"Created initial layout for single-node configuration:\n{}",
				stat.to_message().join("\n")
			);

			garage
				.system
				.layout_manager
				.update_cluster_layout(&layout)
				.await?;
		}
	}

	if (opt.default_bucket || opt.default_access_key) && !opt.single_node {
		return Err(Error::Message(
			"Flags --default-access-key and --default-bucket can only be used in single-node mode."
				.into(),
		));
	}

	if opt.default_access_key || opt.default_bucket {
		let rdenv = |name: &str| {
			std::env::var(name)
				.map_err(|_| Error::Message(format!("Environment variable `{}` is not set", name)))
		};

		// Create default access key if it does not exist
		let key_id = rdenv("GARAGE_DEFAULT_ACCESS_KEY")?;
		let secret_key = rdenv("GARAGE_DEFAULT_SECRET_KEY")?;

		let existing_key = garage.key_table.get(&EmptyKey, &key_id).await?;

		let key = match existing_key {
			Some(key) => {
				match key.state.as_option() {
                    None => return Err(Error::Message(format!("Access key {} was deleted in the cluster, cannot add it back", key_id))),
                    Some(st) if st.secret_key != secret_key => return Err(Error::Message(format!("Access key {} is associated with a secret key different than the one given in GARAGE_DEFAULT_SECRET_KEY", key_id))),
                    _ => (),
                }

				key
			}
			None => {
				info!("Creating default access key `{}`", key_id);

				let mut key = Key::import(&key_id, &secret_key, "default access key")
					.map_err(|e| Error::Message(format!("Invalid default access key: {}", e)))?;
				key.state
					.as_option_mut()
					.unwrap()
					.allow_create_bucket
					.update(true);
				garage.key_table.insert(&key).await?;

				key
			}
		};

		if opt.default_bucket {
			// Create default bucket if it does not exist
			let bucket_name = rdenv("GARAGE_DEFAULT_BUCKET")?;

			if !is_valid_bucket_name(&bucket_name, garage.config.allow_punycode) {
				return Err(Error::Message(
					"Invalid default bucket name, see S3 specification for allowed bucket names."
						.into(),
				));
			}

			let helper = garage.locked_helper().await;

			let bucket = match helper.bucket().resolve_global_bucket_fast(&bucket_name)? {
				Some(bucket) => bucket,
				None => {
					info!("Creating default bucket `{}`", bucket_name);

					let bucket = Bucket::new();
					garage.bucket_table.insert(&bucket).await?;

					helper
						.set_global_bucket_alias(bucket.id, &bucket_name)
						.await
						.map_err(|e| {
							Error::Message(format!("Cannot create default bucket: {}", e))
						})?;

					bucket
				}
			};

			helper
				.set_bucket_key_permissions(
					bucket.id,
					&key.key_id,
					BucketKeyPerm {
						timestamp: now_msec(),
						allow_read: true,
						allow_write: true,
						allow_owner: true,
					},
				)
				.await
				.map_err(|e| {
					Error::Message(format!(
						"Cannot configure permissions on default bucket: {}",
						e
					))
				})?;
		}
	}

	Ok(())
}

#[cfg(unix)]
fn watch_shutdown_signal() -> watch::Receiver<bool> {
	use tokio::signal::unix::*;

	let (send_cancel, watch_cancel) = watch::channel(false);
	tokio::spawn(async move {
		let mut sigint = signal(SignalKind::interrupt()).expect("Failed to install SIGINT handler");
		let mut sigterm =
			signal(SignalKind::terminate()).expect("Failed to install SIGTERM handler");
		let mut sighup = signal(SignalKind::hangup()).expect("Failed to install SIGHUP handler");
		loop {
			tokio::select! {
					_ = sigint.recv() => {
						info!("Received SIGINT, shutting down.");
						break
					}
					_ = sigterm.recv() => {
						info!("Received SIGTERM, shutting down.");
						break
					}
					_ = sighup.recv() => {
						info!("Received SIGHUP, reload not supported.");
						continue
					}
			}
		}
		send_cancel.send(true).unwrap();
	});
	watch_cancel
}

#[cfg(windows)]
fn watch_shutdown_signal() -> watch::Receiver<bool> {
	use tokio::signal::windows::*;

	let (send_cancel, watch_cancel) = watch::channel(false);
	tokio::spawn(async move {
		let mut sigint = ctrl_c().expect("Failed to install Ctrl-C handler");
		let mut sigclose = ctrl_close().expect("Failed to install Ctrl-Close handler");
		let mut siglogoff = ctrl_logoff().expect("Failed to install Ctrl-Logoff handler");
		let mut sigsdown = ctrl_shutdown().expect("Failed to install Ctrl-Shutdown handler");
		tokio::select! {
			_ = sigint.recv() => info!("Received Ctrl-C, shutting down."),
			_ = sigclose.recv() => info!("Received Ctrl-Close, shutting down."),
			_ = siglogoff.recv() => info!("Received Ctrl-Logoff, shutting down."),
			_ = sigsdown.recv() => info!("Received Ctrl-Shutdown, shutting down."),
		}
		send_cancel.send(true).unwrap();
	});
	watch_cancel
}

